import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import{execFileSync}from'node:child_process';import{hash,json}from'./bounded-source-hash-20261026.mjs';
const c=json('CURRENT_CHECKPOINT.json').activeWork.current,pin=c.latestNativeBuild.source,parent=json(pin.path),stage='F:/VisibleMedicine/staging/20261027-cardiac-imaging-native',atlas=stage+'/atlas';
assert.equal(hash(pin.path),pin.sha256);assert.equal(parent.head,'7181b153132b55a682ddbe6558f5dca181643bf0');assert.deepEqual(c.activeExecutionSessions,[]);assert.equal(c.ownerPreviewPolicy.restartPermitted,false);assert(c.ownerWslPolicy.keepRunning);
const git=(...a)=>execFileSync('git',a,{encoding:'utf8',windowsHide:true,env:{...process.env,GIT_OPTIONAL_LOCKS:'0',GIT_NO_REPLACE_OBJECTS:'1'}}).trim();assert.equal(git('-C',parent.atlas,'rev-parse','HEAD'),parent.head);assert.equal(git('-C',parent.atlas,'status','--porcelain'),'');assert(!fs.existsSync(stage));fs.mkdirSync(stage);
git('clone','--shared','--no-checkout','--',parent.atlas,atlas);git('-C',atlas,'config','--local','core.autocrlf','false');git('-C',atlas,'read-tree','HEAD');
for(const r of [...parent.sourceRows,...parent.publicRows]){const from=parent.atlas+'/'+r.path,to=path.resolve(atlas,r.path);assert(to.startsWith(path.resolve(atlas)+path.sep));assert.equal(hash(from),r.sha256);if(fs.existsSync(to)){assert.equal(hash(to),r.sha256);continue;}fs.mkdirSync(path.dirname(to),{recursive:true});fs.copyFileSync(from,to,fs.constants.COPYFILE_EXCL);}
fs.symlinkSync(fs.realpathSync.native(parent.atlas+'/node_modules'),atlas+'/node_modules','junction');assert.equal(git('-C',atlas,'status','--porcelain'),'');
fs.writeFileSync(stage+'/PREPARATION.json',JSON.stringify({at:new Date().toISOString(),atlas,parent:{...pin,head:parent.head,tree:parent.tree},websiteParent:c.latestVerifiedWebsite.source,originalAllSourceAndPublicBytesExact:true,normalPreviewChanged:false},null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({stage,head:parent.head,sourceRows:parent.sourceRows.length,publicRows:parent.publicRows.length}));
